// Default permission sets of the system roles — the source for docs/architecture/rbac-matrix.md (generated by
// `pnpm --filter @idrok/shared rbac:matrix`, checked by a test). Data scope (own groups, own child) is enforced in
// the API services on top of these codes.
import { PERMISSION_CODES, type PermissionCode } from "./permissions";
import type { SystemRoleCode } from "./roles";

const STRUCTURE_VIEW: PermissionCode[] = [
  "academic_years.view",
  "class_groups.view",
  "subjects.view",
  "teacher_assignments.view",
];
const PEOPLE_VIEW: PermissionCode[] = ["students.view", "guardians.view", "employees.view"];
const LESSONS_VIEW: PermissionCode[] = ["timetable.view", "lessons.view", "curriculum.view", "curriculum.export"];
// Teachers plan and mark only their own groups (scope in the services).
const ASSESSMENT_VIEW: PermissionCode[] = ["gradebook.view", "assessment.view"];
const TEACHING: PermissionCode[] = [
  ...LESSONS_VIEW,
  "lessons.mark",
  "curriculum.create",
  ...ASSESSMENT_VIEW,
  "scores.create",
  "assessment.manual_entry",
];

const SCHOOL_ADMIN: PermissionCode[] = PERMISSION_CODES.filter((c) => !c.startsWith("portal."));

export const ROLE_DEFAULT_PERMISSIONS: Record<SystemRoleCode, readonly PermissionCode[]> = {
  SUPER_ADMIN: SCHOOL_ADMIN,
  SCHOOL_ADMIN,
  DIRECTOR: [
    "users.view",
    "roles.view",
    "settings.view",
    ...STRUCTURE_VIEW,
    ...PEOPLE_VIEW,
    ...LESSONS_VIEW,
    ...ASSESSMENT_VIEW,
    "exports.run",
    "audit_logs.view",
  ],
  DEPUTY_DIRECTOR: [
    "users.view",
    "settings.view",
    ...STRUCTURE_VIEW,
    "academic_years.manage",
    "class_groups.manage",
    "subjects.manage",
    "teacher_assignments.manage",
    ...PEOPLE_VIEW,
    "students.create",
    "students.update",
    "guardians.manage",
    "imports.run",
    "exports.run",
    "audit_logs.view",
    // Q-05: deputy director and methodist approve curriculum plans
    "calendar.manage",
    "timetable.manage",
    "timetable.publish",
    ...LESSONS_VIEW,
    "curriculum.approve",
    // M3: policies, period closing and late corrections; reopening a closed period stays with the admin
    ...ASSESSMENT_VIEW,
    "assessment.manage",
    "assessment.approve",
    "scores.correct",
    "scores.late_entry",
  ],
  METHODIST: [
    ...STRUCTURE_VIEW,
    "students.view",
    "employees.view",
    "exports.run",
    ...LESSONS_VIEW,
    "curriculum.approve",
    ...ASSESSMENT_VIEW,
  ],
  TEACHER: [...STRUCTURE_VIEW, "students.view", ...TEACHING],
  CLASS_TEACHER: [...STRUCTURE_VIEW, "students.view", "guardians.view", ...TEACHING],
  STUDENT: ["portal.student"],
  GUARDIAN: ["portal.guardian"],
};

